mapper.select:
SELECT oob.order_receiver_contact, oob.order_shipping_code, oor.return_cash, oob.shop_id, oob.shop_name, oor.order_id, oor.return_code, oor.return_type, oor.return_add_time, oor.return_state, oor.return_message, oor.return_reason, oor.return_shipping_code, oor.order_goods_num, oob.drop_shipping, rp.intervention_state, oob.order_payment_amount, oor.expiration_time, oob.order_source, oob.deliver_shop_id, oor.return_method_status, oob.deliver_shop_name FROM ${database.prefix.order}hou_order_return oor LEFT join ${database.prefix.order}hou_order_base oob ON oob.order_id = oor.order_id LEFT join ${database.prefix.order}hou_order_return_platform rp ON rp.order_id = oor.order_id where oor.return_method_status = 4
and DATE_ADD(now(), INTERVAL 6 HOUR) >= oor.expiration_time and oor.return_state = 1
and oor.return_state = #{param.returnState}
and oor.order_id like concat('%', #{param.orderId}, '%')
and oor.return_code like concat('%', #{param.returnCode}, '%')
and rp.intervention_state = #{param.platformIntervention}
and oor.return_add_time between #{param.returnAddTime} and #{param.returnFinishTime}
and ((oob.shop_id = #{param.shopId} AND oob.original_order IS NULL) or( oob.deliver_shop_id = #{param.shopId} AND oob.original_order IS NOT NULL))
and ((oob.shop_id = #{param.shopId} AND oob.original_order IS NULL) or( oob.deliver_shop_id = #{param.shopId} AND oob.original_order IS NOT NULL)) and oor.return_type = 3
and oob.deliver_shop_name like concat('%', #{param.deliverShopName}, '%')
and oob.drop_shipping = #{param.dropShipping}
ORDER BY oor.return_add_time desc

SELECT oor.return_state, oor.order_goods_num, oor.return_code, oor.return_cash, oor.return_commision_fee, oor.return_reason, oor.return_add_time, oor.return_shop_message, oor.return_shop_time, oor.order_id, oor.buyer_user_account, gmsb.shop_name, oob.payment_name, oob.payment_number, oob.payment_time, oob.order_payment_amount, oor.order_operator_time, oor.return_payment_voucher FROM ${database.prefix.order}hou_order_base oob, ${database.prefix.order}hou_order_return oor left join ${database.prefix.supplier}hou_shop_base gmsb on oor.shop_id = gmsb.supplier_shop_id WHERE oob.order_id = oor.order_id and oor.return_method_status = 4
and oor.return_state = #{param.returnState}
and oob.original_order is null
and oor.return_code like concat('%',#{param.returnCode},'%')
and oor.shop_name like concat('%',#{param.shopName},'%')
and oor.buyer_user_account like concat('%',#{param.buyerUserAccount},'%')
and oor.order_id like concat('%',#{param.orderId},'%')
and oor.return_add_time >= #{param.returnStartTime}
and oor.return_add_time <= #{param.returnFinishTime}
order by oor.return_add_time desc

SELECT oob.deliver_shop_name, oob.order_receiver_contact, oob.order_shipping_code, oor.return_cash, oob.shop_id, oob.shop_name, oor.order_id, oor.return_code, oor.return_type, oor.return_add_time, oor.return_state, oor.return_message, oor.return_reason, oor.return_shipping_code, oor.order_goods_num, oob.drop_shipping, oob.order_payment_amount, oor.expiration_time, oob.order_source, oob.deliver_shop_id, oor.return_method_status, oob.deliver_shop_name, oor.is_send_back, oor.send_back_notes FROM ${database.prefix.order}hou_order_return oor LEFT join ${database.prefix.order}hou_order_base oob ON oob.order_id = oor.order_id where oor.return_method_status = 4 and oob.shop_id != oob.deliver_shop_id AND oob.original_order IS NOT NULL and oob.drop_shipping = 1
and oob.shop_id = #{param.shopId}
and oor.return_state = #{param.returnState}
and oor.return_code like concat('%',#{param.returnCode},'%')
and oor.deliver_shop_name like concat('%',#{param.deliverShopName},'%')
and oor.order_id like concat('%', #{param.orderId}, '%')
and oor.return_add_time between #{param.returnAddTime} and #{param.returnFinishTime}
and oor.is_send_back = #{param.isSendBack}
